    constexpr int FONT_FIRST = 32;
    constexpr int FONT_LAST = 95; // '_'

    char Upper(char c) { return (c >= 'a' && c <= 'z') ? static_cast<char>(c - 32) : c; }

    const unsigned char* Glyph(char c)
    {
        int idx = static_cast<int>(Upper(c));
        if (idx < FONT_FIRST || idx > FONT_LAST)
            idx = FONT_FIRST; // unknown -> space
        return FONT5X7[idx - FONT_FIRST];
    }
