namespace font
{
    int TextWidth(int scale, const char* text)
    {
        int n = text ? static_cast<int>(std::strlen(text)) : 0;
        return n * GLYPH_ADVANCE * scale;
    }

    int DrawText(int x, int y, int scale, const char* text, int r, int g, int b)
    {
        if (!text || scale <= 0)
            return x;

        for (const char* p = text; *p; ++p)
        {
            if (*p == ' ')
            {
                x += GLYPH_ADVANCE * scale;
                continue;
            }
            const unsigned char* rows = Glyph(*p);
            for (int row = 0; row < GLYPH_H; ++row)
            {
                const unsigned bits = rows[row];
                // Run-length encode the 5-bit row into horizontal spans, drawing
                // each span as one rect (bit4 = leftmost column).
                int col = 0;
                while (col < GLYPH_W)
                {
                    if (!((bits >> (GLYPH_W - 1 - col)) & 1))
                    {
                        ++col;
                        continue;
                    }
                    int start = col;
                    while (col < GLYPH_W && ((bits >> (GLYPH_W - 1 - col)) & 1))
                        ++col;
                    const int span = col - start;
                    game::DrawRect(x + start * scale, y + row * scale, span * scale, scale, r, g, b);
                }
            }
            x += GLYPH_ADVANCE * scale;
        }
        return x;
    }
} // namespace font
